{
  "participants": [
    {
      "login": "darosior",
      "stance": "objection",
      "note": "worried earlier revision altered protocol behavior by flooding fRelay=false peers with non-filtered invs"
    },
    {
      "login": "gmaxwell",
      "stance": "objection",
      "note": "argued fRelay=false peers should not be allowed to request mempool inventory"
    },
    {
      "login": "schildbach",
      "stance": "neutral",
      "note": "confirmed bitcoinj SPV behavior sends filterload before mempool"
    }
  ],
  "claims": [
    {
      "id": "rc:3714751926",
      "kind": "correctness",
      "harm": "Floods fRelay=false peers with unfiltered transaction invs after a mempool request, constituting an unintended protocol change.",
      "quote": "Prior to this we would not flood a peer that set BIP 37 `fRelay` to `false` with INV's until they set a filter. After this change, we would flood them with non-filtered INV's provided they previously sent a MEMPOOL message.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3715856447",
        "c:5300547959"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3715856447",
      "settled_by_quote": "To make sure, I added a test that requests a BIP35 snapshot and verifies that a transaction added afterward is announced to a regular relay peer but not to the requester. It passes before and after the production change."
    },
    {
      "id": "c:5274016638",
      "kind": "approach",
      "harm": "Allowing fRelay=false peers to request mempool inventory moots bandwidth reduction and surveillance privacy assumptions.",
      "quote": "Should fRelay=false be able to request inventory at all? ... I think it probably shouldn't be allowed.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:5275580899",
        "c:5300547959"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:5300547959",
      "settled_by_quote": "The PR now ignores non-permissioned `mempool` requests while tx relay is disabled, preserving existing BIP37 and targeted `getdata` behavior."
    }
  ],
  "support": [],
  "notes": "Initial record. darosior raised a concern about unintended inv flooding which l0rinc addressed with test verification, and gmaxwell suggested disallowing mempool requests from fRelay=false peers, prompting l0rinc to rebase and rework the implementation after checking SPV sequencing with bitcoinj maintainer schildbach."
}
